-- Course 9, unit 13: the order list GET /api/v1/orders pages (OrderPages, by a signed cursor over Spring Data's keyset). One row per order.
-- amount, never value: VALUE is a reserved word in H2, and a column named so stops this migration there.
-- Seeded here with twenty orders, two a minute, so two orders share every placed_at: the id breaks the tie. The same file runs on
-- H2 and PostgreSQL (no branch). No route writes this table: a public write route for orders is not in Course 9.
CREATE TABLE tiffin_order (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer  VARCHAR(60) NOT NULL,
    meal_type VARCHAR(10) NOT NULL,
    amount    INT         NOT NULL,
    placed_at TIMESTAMP(6) WITH TIME ZONE NOT NULL
);
